import request from 'supertest';
import { describe, expect, it } from 'vitest';
import { createApp } from '../src/app.ts';

const app = () => request(createApp());
const valid = { email: 'a@example.com', name: 'Alice' };

describe('users API', () => {
  it('creates, gets, updates and deletes a user', async () => {
    const created = await app().post('/v1/users').send(valid);
    expect(created.status).toBe(201);
    expect(created.headers.location).toMatch(/^\/v1\/users\//);
    expect(created.body).toMatchObject({ ...valid, role: 'member' });
    expect(created.body.id).toEqual(expect.any(String));
    expect(created.body.createdAt).toEqual(expect.any(String));
    const id = created.body.id as string;
    expect((await app().get(`/v1/users/${id}`)).body).toEqual(created.body);
    const patched = await app().patch(`/v1/users/${id}`).send({ name: 'Alicia', role: 'admin' });
    expect(patched.status).toBe(200);
    expect(patched.body).toMatchObject({ id, email: valid.email, name: 'Alicia', role: 'admin' });
    expect((await app().delete(`/v1/users/${id}`)).status).toBe(204);
    expect((await app().get(`/v1/users/${id}`)).status).toBe(404);
  });

  it('rejects duplicate email on create and patch', async () => {
    await app().post('/v1/users').send(valid);
    const second = await app().post('/v1/users').send({ email: 'b@example.com', name: 'Bob' });
    expect((await app().post('/v1/users').send({ email: valid.email, name: 'Other' })).status).toBe(409);
    expect((await app().patch(`/v1/users/${second.body.id}`).send({ email: valid.email })).status).toBe(409);
  });

  it('validates body, query, path and malformed JSON as problem details', async () => {
    expect((await app().post('/v1/users').send({ email: 'bad', name: '' })).status).toBe(422);
    expect((await app().get('/v1/users?limit=101')).status).toBe(422);
    expect((await app().get('/v1/users/not-a-uuid')).status).toBe(422);
    expect((await app().patch('/v1/users/not-a-uuid').send({})).status).toBe(422);
    expect((await app().post('/v1/users').set('Content-Type', 'application/json').send('{')).status).toBe(400);
  });

  it('cursor paginates all users exactly once', async () => {
    for (const name of ['One', 'Two', 'Three']) await app().post('/v1/users').send({ email: `${name}@example.com`, name });
    const ids: string[] = [];
    let cursor: string | undefined;
    do {
      const response = await app().get('/v1/users').query({ limit: 2, cursor });
      expect(response.status).toBe(200);
      ids.push(...(response.body.data as Array<{ id: string }>).map((u) => u.id));
      cursor = response.body.nextCursor ?? undefined;
    } while (cursor !== undefined);
    expect(new Set(ids).size).toBe(3);
  });

  it('replays idempotent creates and rejects changed reuse', async () => {
    const first = await app().post('/v1/users').set('Idempotency-Key', 'key').send(valid);
    const replay = await app().post('/v1/users').set('Idempotency-Key', 'key').send(valid);
    expect(replay.status).toBe(201);
    expect(replay.headers['idempotent-replayed']).toBe('true');
    expect(replay.body).toEqual(first.body);
    expect((await app().post('/v1/users').set('Idempotency-Key', 'key').send({ email: 'new@example.com', name: 'New' })).status).toBe(422);
  });
});

import { Router, type Request, type Response } from 'express';
import { randomUUID } from 'node:crypto';
import { z } from 'zod';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';
import { CursorQuerySchema, paginate, pageSchema } from '../lib/pagination.ts';
import { idempotency } from '../lib/idempotency.ts';

const UserSchema = z.object({ id: z.uuid(), email: z.email(), name: z.string().min(1).max(100), role: z.enum(['admin', 'member']), createdAt: z.iso.datetime(), updatedAt: z.iso.datetime() });
const CreateSchema = z.object({ email: z.email(), name: z.string().min(1).max(100), role: z.enum(['admin', 'member']).default('member') }).strict();
const PatchSchema = CreateSchema.partial().strict();
const IdSchema = z.object({ userId: z.uuid() });
type User = z.infer<typeof UserSchema>;

export function usersRouter(): Router {
  const router = Router();
  const users: User[] = [];
  const find = (id: string): User => { const user = users.find((item) => item.id === id); if (!user) throw notFound(`User ${id} was not found.`); return user; };
  router.post('/v1/users', idempotency(), (req: Request, res: Response) => {
    const input = CreateSchema.parse(req.body);
    if (users.some((u) => u.email === input.email)) throw conflict('email: already exists');
    const now = new Date().toISOString();
    const user = UserSchema.parse({ ...input, id: randomUUID(), createdAt: now, updatedAt: now });
    users.push(user); res.location(`/v1/users/${user.id}`).status(201).json(UserSchema.parse(user));
  });
  router.get('/v1/users', (req: Request, res: Response) => { const query = CursorQuerySchema.parse(req.query); res.json(pageSchema(UserSchema).parse(paginate(users, query, (u) => u.id))); });
  router.get('/v1/users/:userId', (req: Request, res: Response) => { const { userId } = IdSchema.parse(req.params); res.json(UserSchema.parse(find(userId))); });
  router.patch('/v1/users/:userId', idempotency(), (req: Request, res: Response) => { const { userId } = IdSchema.parse(req.params); const user = find(userId); const input = PatchSchema.parse(req.body); if (Object.keys(input).length === 0) throw unprocessable('body: must not be empty'); if (input.email && users.some((u) => u.id !== userId && u.email === input.email)) throw conflict('email: already exists'); Object.assign(user, input, { updatedAt: new Date().toISOString() }); res.json(UserSchema.parse(user)); });
  router.delete('/v1/users/:userId', (req: Request, res: Response) => { const { userId } = IdSchema.parse(req.params); find(userId); users.splice(users.findIndex((u) => u.id === userId), 1); res.status(204).send(); });
  return router;
}

import type { Router } from 'express';
import { usersRouter } from './users.ts';

export function registerRoutes(app: Router): void {
  app.use(usersRouter());
}

