import { Router, type Request, type Response, type NextFunction } from 'express';
import crypto from 'node:crypto';
import { z } from 'zod';
import { idempotency } from '../lib/idempotency.ts';
import { CursorQuerySchema, paginate, pageSchema } from '../lib/pagination.ts';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';

const UserSchema = z.object({ id: z.string().uuid(), email: z.string().email(), name: z.string().min(1).max(100), role: z.enum(['admin', 'member']), createdAt: z.string().datetime(), updatedAt: z.string().datetime() });
const CreateSchema = z.object({ email: z.string().email(), name: z.string().min(1).max(100), role: z.enum(['admin', 'member']).default('member') }).strict();
const PatchSchema = z.object({ email: z.string().email().optional(), name: z.string().min(1).max(100).optional(), role: z.enum(['admin', 'member']).optional() }).strict().refine((v) => Object.keys(v).length > 0, 'at least one field is required');
const IdSchema = z.object({ userId: z.string().uuid() });
type User = z.infer<typeof UserSchema>;

function validation(next: NextFunction): (err: unknown) => void { return (err) => { if (err instanceof z.ZodError) next(unprocessable(err.issues.map((i) => i.path.join('.') || 'request').join(', '))); else next(err); }; }

export function usersRouter(): Router {
  const router = Router();
  const users: User[] = [];
  const createIdempotency = idempotency();
  const patchIdempotency = idempotency();
  const find = (id: string): User => { const user = users.find((item) => item.id === id); if (!user) throw notFound(`User ${id} was not found.`); return user; };
  const unique = (email: string, id?: string): void => { if (users.some((u) => u.email === email && u.id !== id)) throw conflict('A user with this email already exists.'); };
  const wrap = (handler: (req: Request, res: Response) => void): ((req: Request, res: Response, next: NextFunction) => void) => (req, res, next) => { try { handler(req, res); } catch (err) { validation(next)(err); } };

  router.get('/v1/users', wrap((req, res) => { const query = CursorQuerySchema.parse(req.query); const page = paginate(users, query, (u) => u.id); res.status(200).json(pageSchema(UserSchema).parse(page)); }));
  router.post('/v1/users', createIdempotency, wrap((req, res) => { const input = CreateSchema.parse(req.body); unique(input.email); const now = new Date().toISOString(); const user = UserSchema.parse({ ...input, id: crypto.randomUUID(), createdAt: now, updatedAt: now }); users.push(user); res.location(`/v1/users/${user.id}`).status(201).json(user); }));
  router.get('/v1/users/:userId', wrap((req, res) => res.status(200).json(UserSchema.parse(find(IdSchema.parse(req.params).userId))));
  router.patch('/v1/users/:userId', patchIdempotency, wrap((req, res) => { const user = find(IdSchema.parse(req.params).userId); const patch = PatchSchema.parse(req.body); if (patch.email !== undefined) unique(patch.email, user.id); Object.assign(user, patch, { updatedAt: new Date().toISOString() }); res.status(200).json(UserSchema.parse(user)); }));
  router.delete('/v1/users/:userId', wrap((req, res) => { const id = IdSchema.parse(req.params).userId; find(id); users.splice(users.findIndex((u) => u.id === id), 1); res.status(204).send(); }));
  return router;
}

